            /** @description ILLUSTRATIVE_TEST_DATA when the rule set is made-up test data, not an underwriting guideline (D-SLC-04) */
            dataStatus?: string;
            /** @description e.g. UW-WARN-ILLUSTRATIVE-RULES */
            warnings?: string[];
            ruleSetCode?: components["schemas"]["Code"];
            ruleSetVersion?: string;
            /** @description Content hash of the decision table that was evaluated (REQ-UW-042) */
            ruleSetHash?: components["schemas"]["Sha256"];
